export type AuditEvent = AuditEvent_Serialize | AuditEvent_Deserialize;

/**  审计事件类型。**只增不改**：改名会让历史日志失去可读性。 */
export type AuditEventKind = 
/**  插件被安装 */
"installed" | 
/**  插件被卸载 */
"uninstalled" | 
/**  用户授予了能力 */
"permissionGranted" | 
/**  用户收回了能力 */
"permissionRevoked" | 
/**  **检测到权限扩张**（新版本声明了旧版本没有的能力） */
"privilegeEscalation" | 
/**  **运行时越权被拦截** —— 用了没声明/没授权的能力 */
"capabilityViolation" | 
/**
 *  **路径逃逸被拦截** —— 插件试图访问授权根之外的路径。
 * 
 *  与 [`AuditEventKind::CapabilityViolation`] 分开记，因为它们的**排查含义不同**：
 *  前者是"插件声明漏了/用户没授权"，后者是"有人在试探沙箱边界"。
 *  事后取证时这两件事的严重程度不一样，混在一起就分不出来了。
 * 
 *  这条是被一次真机测试逼出来的：我装了一个步骤里写死
 *  `C:\Windows\System32\drivers\etc\hosts` 的恶意插件并运行，任务被正确拒绝，
 *  **但审计日志里什么都没有** —— 因为拦截来自 `PathResolver`（`PermissionDenied`），
 *  而当时的审计钩子只认能力裁决的 `PluginCapabilityViolation`。
 */
"pathEscapeBlocked" | 
/**  清单校验失败 */
"validationFailed" | 
/**  哈希不匹配（装载时或下载时） */
"integrityFailure" | 
/**  AI 生成的插件通过审核并落盘 */
"aiDraftAccepted" | 
/**  AI 生成的插件被拒绝 */
"aiDraftRejected";

export type AuditEvent_Deserialize = {
	/**  ISO-8601 */
	at: string,
	kind: AuditEventKind,
	/**  相关插件 / 引擎 / 请求的标识 */
	subject?: string | null,
	/**  人类可读的摘要 */
	summary: string,
	/**
	 *  结构化补充信息，**以 JSON 文本形式存放**。
	 * 
	 *  为什么不用 `serde_json::Value`：它是无界递归类型
	 *  （`Value` → `Vec<Value>` → `Value`），specta 导出时会产生无限展开的 TS 类型
	 *  并直接报错。存成字符串后前端按需 `JSON.parse(e.detail)` 即可，
	 *  而写入端（[`AuditEvent::detail`]）仍然接受结构化值。
	 */
	detail?: string | null,
};

export type AuditEvent_Serialize = {
	/**  ISO-8601 */
	at: string,
	kind: AuditEventKind,
	/**  相关插件 / 引擎 / 请求的标识 */
	subject?: string | null,
	/**  人类可读的摘要 */
	summary: string,
	/**
	 *  结构化补充信息，**以 JSON 文本形式存放**。
	 * 
	 *  为什么不用 `serde_json::Value`：它是无界递归类型
	 *  （`Value` → `Vec<Value>` → `Value`），specta 导出时会产生无限展开的 TS 类型
	 *  并直接报错。存成字符串后前端按需 `JSON.parse(e.detail)` 即可，
	 *  而写入端（[`AuditEvent::detail`]）仍然接受结构化值。
	 */
	detail?: string | null,
};

