/**
 *  插件声明的一项能力。
 * 
 *  serde 用 `kind` 做 tag，导出到 TS 就是可判别联合 ——
 *  前端可以直接 `switch (cap.kind)` 生成权限勾选界面，不需要额外映射表。
 */
export type Capability = 
/**  读文件 */
{ kind: "fsRead"; scope: PathScope } | 
/**  写文件 */
{ kind: "fsWrite"; scope: PathScope } | 
/**  出网。`hosts` 为空表示"任意主机"，非空则只允许这些主机（后缀匹配）。 */
{ kind: "net"; hosts: string[] } | 
/**  启动子进程 */
{ kind: "exec" } | 
/**  读取指定的环境变量（白名单，避免插件顺手把 API key 读走） */
{ kind: "env"; names: string[] } | 
/**  调用大模型服务（会计入用户额度） */
{ kind: "ai" } | 
/**  使用 GPU */
{ kind: "gpu" };

/**  草稿里的一个文件 */
export type DraftFile = {
	path: string,
	content: string,
	language: string,
};

